<?php require 'config.php';if(is_admin())go('admin/index.php');$error='';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$s=$pdo->prepare("SELECT * FROM admins WHERE email=?");$s->execute([trim($_POST['email']??'')]);$a=$s->fetch();if($a&&password_verify($_POST['password']??'',$a['password_hash'])){session_regenerate_id(true);$_SESSION['admin_id']=$a['id'];$_SESSION['admin_name']=$a['name'];go('admin/index.php');}$error='Email atau password salah.';}$page_title='Login Admin';require 'header.php';?><div class="auth panel"><h1>Login Admin</h1><?php if($error):?><p class="alert"><?=e($error)?></p><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><label>Email<input type="email" name="email" required></label><label>Password<input type="password" name="password" required></label><button class="btn">Masuk</button></form></div><?php require 'footer.php';?>